cypress_script:
describe('Asynchronously Loaded Content', () => {
  it('should load content after clicking Start button', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('button').contains('Start').click();
    cy.get('#finish').should('be.visible');
  });
  it('should not load content without clicking the Start button', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('#finish').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Asynchronously Loaded Content', () => {
  test('should load content after clicking Start button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await page.click('button:has-text("Start")');
    await expect(page.locator('#finish')).toBeVisible();
  });
  test('should not load content without clicking the Start button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await expect(page.locator('#finish')).not.toBeVisible();
  });
});
